<?php include __DIR__.'/_tabs.php';if(!$o)echo '<p class="muted">Aún no tienes pedidos.</p>';?>
<table><?php foreach($o as $x):?><tr><td>#<?=$x['oid']?></td><td><?=e($x['name'])?> × <?=$x['qty']?><br><small class="muted"><?=e($x['buyer'])?> · <?=e($x['address'])?></small></td><td><?=money($x['qty']*$x['price'])?></td><td><form method="post" action="<?=url('panel/estado')?>"><input type="hidden" name="t" value="<?=csrf()?>"><input type="hidden" name="item" value="<?=$x['id']?>"><select name="status" onchange="this.form.submit()"><?php foreach(['pendiente','enviado','entregado'] as $s)echo '<option '.($x['status']===$s?'selected':'').'>'.$s.'</option>';?></select></form></td></tr><?php endforeach;?></table>